{"content":""""
Example Agent Implementation

This is a simple example agent that demonstrates how to use the Agent SDK.
"""

import time
import logging
from sdk.agent_base import AgentBase
from sdk.agent_config import AgentConfig


logger = logging.getLogger(__name__)


class ExampleAgent(AgentBase):
    """Example agent that processes simple tasks"""

    def execute_task(self, task):
        """Execute a task"""

        task_type = task.get("type", "unknown")
        task_data = task.get("data", {})

        logger.info(f"Processing task type: {task_type}")

        if task_type == "echo":
            # Simple echo task
            message = task_data.get("message", "")
            return {"echo": message}

        elif task_type == "compute":
            # Simple computation task
            operation = task_data.get("operation", "add")
            a = task_data.get("a", 0)
            b = task_data.get("b", 0)

            if operation == "add":
                result = a + b
            elif operation == "multiply":
                result = a * b
            elif operation == "subtract":
                result = a - b
            elif operation == "divide":
                result = a / b if b != 0 else None
            else:
                result = None

            return {"result": result}

        elif task_type == "sleep":
            # Sleep task (for testing)
            duration = task_data.get("duration", 1)
            time.sleep(duration)
            return {"slept": duration}

        else:
            return {"error": f"Unknown task type: {task_type}"}

    def on_start(self):
        """Called when agent starts"""
        logger.info("Example agent starting...")

    def on_stop(self):
        """Called when agent stops"""
        logger.info("Example agent stopping...")

    def on_task_received(self, task):
        """Called when task is received"""
        logger.info(f"Task received: {task.get('id')}")

    def on_task_completed(self, task, result):
        """Called when task completes"""
        logger.info(f"Task completed: {task.get('id')} -> {result}")

    def on_task_failed(self, task, error):
        """Called when task fails"""
        logger.error(f"Task failed: {task.get('id')} -> {error}")


if __name__ == "__main__":
    # Create config from environment
    config = AgentConfig.from_env(
        agent_id="example-agent-1",
        agent_name="Example Agent"
    )

    # Add capabilities
    config.capabilities = ["echo", "compute", "sleep"]
    config.metadata = {
        "version": "1.0.0",
        "description": "Example agent for testing"
    }

    # Create and run agent
    agent = ExampleAgent(config)
    agent.run()
