{"content":""""
Task Router - Intelligent task assignment and load balancing
"""

import logging
import time
from typing import Dict, Any, Optional, List
from dataclasses import dataclass
from enum import Enum


logger = logging.getLogger(__name__)


class RoutingStrategy(Enum):
    """Task routing strategies"""
    ROUND_ROBIN = "round_robin"
    LEAST_LOADED = "least_loaded"
    CAPABILITY_MATCH = "capability_match"
    PRIORITY_BASED = "priority_based"


@dataclass
class AgentLoad:
    """Agent load information"""
    agent_id: str
    active_tasks: int
    max_tasks: int
    capabilities: List[str]
    last_assigned: float

    @property
    def load_percentage(self) -> float:
        """Calculate load percentage"""
        if self.max_tasks == 0:
            return 100.0
        return (self.active_tasks / self.max_tasks) * 100

    @property
    def is_available(self) -> bool:
        """Check if agent can accept more tasks"""
        return self.active_tasks < self.max_tasks


class TaskRouter:
    """Route tasks to appropriate agents"""

    def __init__(self, strategy: RoutingStrategy = RoutingStrategy.LEAST_LOADED):
        self.strategy = strategy
        self.agent_loads: Dict[str, AgentLoad] = {}
        self.round_robin_index = 0

        logger.info(f"TaskRouter initialized with strategy: {strategy.value}")

    def register_agent(
        self,
        agent_id: str,
        capabilities: List[str],
        max_tasks: int = 5
    ):
        """Register agent for task routing"""

        self.agent_loads[agent_id] = AgentLoad(
            agent_id=agent_id,
            active_tasks=0,
            max_tasks=max_tasks,
            capabilities=capabilities,
            last_assigned=0
        )

        logger.info(f"Agent registered for routing: {agent_id} (max_tasks={max_tasks})")

    def unregister_agent(self, agent_id: str):
        """Unregister agent"""

        if agent_id in self.agent_loads:
            del self.agent_loads[agent_id]
            logger.info(f"Agent unregistered: {agent_id}")

    def update_agent_load(self, agent_id: str, active_tasks: int):
        """Update agent's active task count"""

        if agent_id in self.agent_loads:
            self.agent_loads[agent_id].active_tasks = active_tasks
            logger.debug(f"Agent load updated: {agent_id} -> {active_tasks} tasks")

    def increment_load(self, agent_id: str):
        """Increment agent's task count"""

        if agent_id in self.agent_loads:
            self.agent_loads[agent_id].active_tasks += 1
            self.agent_loads[agent_id].last_assigned = time.time()

    def decrement_load(self, agent_id: str):
        """Decrement agent's task count"""

        if agent_id in self.agent_loads:
            self.agent_loads[agent_id].active_tasks = max(
                0,
                self.agent_loads[agent_id].active_tasks - 1
            )

    def select_agent(
        self,
        task: Dict[str, Any],
        required_capability: Optional[str] = None
    ) -> Optional[str]:
        """
        Select best agent for task

        Args:
            task: Task data
            required_capability: Required capability

        Returns:
            agent_id or None if no agent available
        """

        # Filter available agents
        available = [
            agent for agent in self.agent_loads.values()
            if agent.is_available
        ]

        if not available:
            logger.warning("No available agents")
            return None

        # Filter by capability if required
        if required_capability:
            available = [
                agent for agent in available
                if required_capability in agent.capabilities
            ]

            if not available:
                logger.warning(f"No agents with capability: {required_capability}")
                return None

        # Select based on strategy
        if self.strategy == RoutingStrategy.ROUND_ROBIN:
            selected = self._round_robin(available)

        elif self.strategy == RoutingStrategy.LEAST_LOADED:
            selected = self._least_loaded(available)

        elif self.strategy == RoutingStrategy.CAPABILITY_MATCH:
            selected = self._capability_match(available, task)

        elif self.strategy == RoutingStrategy.PRIORITY_BASED:
            selected = self._priority_based(available, task)

        else:
            selected = available[0]

        if selected:
            logger.info(f"Task routed to agent: {selected.agent_id} (load: {selected.load_percentage:.1f}%)")
            self.increment_load(selected.agent_id)

        return selected.agent_id if selected else None

    def _round_robin(self, agents: List[AgentLoad]) -> Optional[AgentLoad]:
        """Round-robin selection"""

        if not agents:
            return None

        selected = agents[self.round_robin_index % len(agents)]
        self.round_robin_index += 1

        return selected

    def _least_loaded(self, agents: List[AgentLoad]) -> Optional[AgentLoad]:
        """Select least loaded agent"""

        if not agents:
            return None

        return min(agents, key=lambda a: a.active_tasks)

    def _capability_match(
        self,
        agents: List[AgentLoad],
        task: Dict[str, Any]
    ) -> Optional[AgentLoad]:
        """Select agent with best capability match"""

        if not agents:
            return None

        # For now, just use least loaded
        # TODO: Implement capability scoring
        return self._least_loaded(agents)

    def _priority_based(
        self,
        agents: List[AgentLoad],
        task: Dict[str, Any]
    ) -> Optional[AgentLoad]:
        """Select based on task priority"""

        if not agents:
            return None

        # High priority tasks go to least loaded
        # Normal/low priority can go to any available
        priority = task.get("priority", "normal")

        if priority in ["high", "critical"]:
            return self._least_loaded(agents)
        else:
            return self._round_robin(agents)

    def get_stats(self) -> Dict[str, Any]:
        """Get routing statistics"""

        total_agents = len(self.agent_loads)
        available_agents = sum(1 for a in self.agent_loads.values() if a.is_available)
        total_tasks = sum(a.active_tasks for a in self.agent_loads.values())

        agent_stats = []
        for agent in self.agent_loads.values():
            agent_stats.append({
                "agent_id": agent.agent_id,
                "active_tasks": agent.active_tasks,
                "max_tasks": agent.max_tasks,
                "load_percentage": agent.load_percentage,
                "capabilities": agent.capabilities
            })

        return {
            "strategy": self.strategy.value,
            "total_agents": total_agents,
            "available_agents": available_agents,
            "total_active_tasks": total_tasks,
            "agents": agent_stats
        }
