"""
Complete Agent Example with Task Execution

This example demonstrates a fully functional agent that:
- Registers with the orchestrator
- Sends heartbeats
- Fetches and executes tasks
- Reports results
- Handles errors gracefully
"""

import sys
import time
import logging

sys.path.insert(0, '/usr/local/lib/hermes-orchestrator')

from sdk import AgentBase, AgentConfig


logger = logging.getLogger(__name__)


class WorkerAgent(AgentBase):
    """Worker agent that can execute various task types"""

    def execute_task(self, task):
        """Execute a task based on its type"""

        task_type = task.get("type", "unknown")
        task_data = task.get("data", {})

        logger.info(f"Executing task type: {task_type}")

        if task_type == "echo":
            return self._handle_echo(task_data)

        elif task_type == "compute":
            return self._handle_compute(task_data)

        elif task_type == "sleep":
            return self._handle_sleep(task_data)

        elif task_type == "process":
            return self._handle_process(task_data)

        else:
            raise ValueError(f"Unknown task type: {task_type}")

    def _handle_echo(self, data):
        """Echo task - return input message"""
        message = data.get("message", "")
        return {
            "type": "echo",
            "message": message,
            "length": len(message),
            "timestamp": time.time()
        }

    def _handle_compute(self, data):
        """Compute task - perform calculation"""
        operation = data.get("operation", "add")
        a = data.get("a", 0)
        b = data.get("b", 0)

        if operation == "add":
            result = a + b
        elif operation == "subtract":
            result = a - b
        elif operation == "multiply":
            result = a * b
        elif operation == "divide":
            if b == 0:
                raise ValueError("Division by zero")
            result = a / b
        elif operation == "power":
            result = a ** b
        else:
            raise ValueError(f"Unknown operation: {operation}")

        return {
            "type": "compute",
            "operation": operation,
            "a": a,
            "b": b,
            "result": result
        }

    def _handle_sleep(self, data):
        """Sleep task - simulate long-running work"""
        duration = data.get("duration", 1)

        if duration > 60:
            raise ValueError("Sleep duration too long (max 60s)")

        time.sleep(duration)

        return {
            "type": "sleep",
            "duration": duration,
            "completed_at": time.time()
        }

    def _handle_process(self, data):
        """Process task - simulate data processing"""
        items = data.get("items", [])
        operation = data.get("operation", "count")

        if operation == "count":
            result = len(items)
        elif operation == "sum":
            result = sum(items)
        elif operation == "average":
            result = sum(items) / len(items) if items else 0
        elif operation == "max":
            result = max(items) if items else None
        elif operation == "min":
            result = min(items) if items else None
        else:
            raise ValueError(f"Unknown operation: {operation}")

        return {
            "type": "process",
            "operation": operation,
            "item_count": len(items),
            "result": result
        }

    def on_start(self):
        """Called when agent starts"""
        logger.info("=" * 60)
        logger.info(f"Worker Agent Starting: {self.config.agent_id}")
        logger.info(f"Capabilities: {', '.join(self.config.capabilities)}")
        logger.info(f"Max concurrent tasks: {self.config.max_concurrent_tasks}")
        logger.info("=" * 60)

    def on_stop(self):
        """Called when agent stops"""
        logger.info("=" * 60)
        logger.info(f"Worker Agent Stopping: {self.config.agent_id}")
        logger.info("=" * 60)

    def on_task_received(self, task):
        """Called when task is received"""
        logger.info(f"📥 Task received: {task.get('id')} (type: {task.get('type')})")

    def on_task_completed(self, task, result):
        """Called when task completes"""
        logger.info(f"✅ Task completed: {task.get('id')} -> {result}")

    def on_task_failed(self, task, error):
        """Called when task fails"""
        logger.error(f"❌ Task failed: {task.get('id')} -> {error}")


def main():
    """Main entry point"""

    # Create config from environment
    config = AgentConfig.from_env(
        agent_id="worker-agent-1",
        agent_name="Worker Agent 1"
    )

    # Override with specific settings
    config.capabilities = ["echo", "compute", "sleep", "process"]
    config.metadata = {
        "version": "1.0.0",
        "description": "General purpose worker agent",
        "max_task_duration": 60
    }
    config.max_concurrent_tasks = 3
    config.task_timeout = 60
    config.log_level = "INFO"

    # Create and run agent
    agent = WorkerAgent(config)

    try:
        agent.run()
    except KeyboardInterrupt:
        logger.info("\n🛑 Shutting down gracefully...")
    except Exception as e:
        logger.error(f"Fatal error: {e}", exc_info=True)
        sys.exit(1)


if __name__ == "__main__":
    main()
